import{Z as t,e as a,f as e,a0 as o}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"Email Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"guides/email-notifications/index.md","filePath":"guides/email-notifications/index.md","lastUpdated":1782532814000}'),n={name:"guides/email-notifications/index.md"};function s(r,i,l,c,m,f){return a(),e("div",null,[...i[0]||(i[0]=[o('<h1 id="email-notifications" tabindex="-1">Email Notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email Notifications&quot;">​</a></h1><p>Deliverability, templates, attachments, and notification patterns.</p><h2 id="attaching-extra-assets-to-email-notifications" tabindex="-1"><a href="/guides/email-notifications/attaching-extra-assets-to-email-notifications">Attaching Extra Assets to Email Notifications</a> <a class="header-anchor" href="#attaching-extra-assets-to-email-notifications" aria-label="Permalink to &quot;[Attaching Extra Assets to Email Notifications](/guides/email-notifications/attaching-extra-assets-to-email-notifications)&quot;">​</a></h2><p>Formie can attach files to notification emails in several built-in ways. When those are not enough, hook into the mail event and attach your own files.</p><h2 id="building-an-email-notification-template-from-scratch" tabindex="-1"><a href="/guides/email-notifications/building-an-email-notification-template-from-scratch">Building an Email Notification Template from Scratch</a> <a class="header-anchor" href="#building-an-email-notification-template-from-scratch" aria-label="Permalink to &quot;[Building an Email Notification Template from Scratch](/guides/email-notifications/building-an-email-notification-template-from-scratch)&quot;">​</a></h2><p>Formie sends through Craft&#39;s mailer, so you can wrap notification content in the same branded email layout as the rest of your project.</p><h2 id="create-email-notifications-just-using-twig" tabindex="-1"><a href="/guides/email-notifications/create-email-notifications-just-using-twig">Create Email Notifications Just Using Twig</a> <a class="header-anchor" href="#create-email-notifications-just-using-twig" aria-label="Permalink to &quot;[Create Email Notifications Just Using Twig](/guides/email-notifications/create-email-notifications-just-using-twig)&quot;">​</a></h2><p>Formie exposes its services to Twig like any Craft plugin. You can create notifications programmatically — useful for front-end admin areas or one-off setup templates.</p><h2 id="how-to-keep-email-notifications-out-of-your-junk-emails" tabindex="-1"><a href="/guides/email-notifications/how-to-keep-email-notifications-out-of-your-junk-emails">How to Keep Email Notifications Out of Your Junk Emails</a> <a class="header-anchor" href="#how-to-keep-email-notifications-out-of-your-junk-emails" aria-label="Permalink to &quot;[How to Keep Email Notifications Out of Your Junk Emails](/guides/email-notifications/how-to-keep-email-notifications-out-of-your-junk-emails)&quot;">​</a></h2><p>Spam filters are good at separating legitimate mail from junk — but Formie notification settings can still work against you if they look like spoofed or misconfigured messages. These tips help your Formie emails arrive in the inbox.</p><h2 id="multi-site-notification-content" tabindex="-1"><a href="/guides/email-notifications/multi-site-notification-content">Multi-Site Notification Content</a> <a class="header-anchor" href="#multi-site-notification-content" aria-label="Permalink to &quot;[Multi-Site Notification Content](/guides/email-notifications/multi-site-notification-content)&quot;">​</a></h2><p>Multi-site forms often need notification emails in the right language with the right recipients — without duplicating every form. Formie supports per-site notification overrides in the builder, conditional notifications, and variable-driven single templates. This guide compares the patterns and recommends one for common setups.</p><h2 id="pdf-attachments-with-email-notifications" tabindex="-1"><a href="/guides/email-notifications/pdf-attachments-with-email-notifications">PDF Attachments with Email Notifications</a> <a class="header-anchor" href="#pdf-attachments-with-email-notifications" aria-label="Permalink to &quot;[PDF Attachments with Email Notifications](/guides/email-notifications/pdf-attachments-with-email-notifications)&quot;">​</a></h2><p>Email notifications can attach a generated PDF — useful for invoices, application summaries, signed agreements, or printable copies of what the user submitted. Formie renders a Twig PDF template at send time and attaches the result. This walkthrough creates the template, links it to a notification, and covers layout options.</p>',14)])])}const d=t(n,[["render",s]]);export{h as __pageData,d as default};
